css:
/* Post hero — the handoff's `.hero--post`: a photograph under a 72% scrim with
   the breadcrumb, the title and the byline set left over it, rather than the
   centred treatment every other hero on this site uses.

   scripts/build.mjs composes a post's date and title ahead of its node tree, so
   a post that carries this band would show both: the composed masthead and then
   the hero saying the same thing over the photograph. The masthead is hidden
   wherever this component is placed — and only there, so the posts that do not
   place it keep the masthead and the rules the site layer dresses it with.
   Worth reporting: a post cannot author its own hero without this, because the
   masthead is emitted unconditionally and there is no setting that turns it off. */
article > .bz-block:first-child { display: none; }

[data-bz-section="post-hero"] > .bz-section {
  position: relative;
  overflow: hidden;
  background: var(--chrome);
  padding-block: 88px;
}
/* The photograph is a real image block, so it stays a replaceable slot on the
   canvas; it is lifted out of the container's measure to fill the band. */
[data-bz-section="post-hero"] [data-bz-node="ph-photo"] { position: absolute; inset: 0; z-index: 0; padding: 0; }
[data-bz-section="post-hero"] [data-bz-node="ph-photo"] > .bz-container { height: 100%; max-width: none; padding: 0; }
[data-bz-section="post-hero"] [data-bz-node="ph-photo"] .bz-figure { height: 100%; margin: 0; }
[data-bz-section="post-hero"] [data-bz-node="ph-photo"] img { width: 100%; height: 100%; object-fit: cover; display: block; }
/* --color-hero-scrim. The band reads even when the photograph has not been
   supplied yet, because the scrim sits on the near-black chrome colour. */
[data-bz-section="post-hero"] > .bz-section::after {
  content: ""; position: absolute; inset: 0; background: rgba(20, 20, 20, .72); pointer-events: none; z-index: 1;
}
/* The photograph, the scrim and the copy are three layers in the section's own
   stacking context, so the container must not open one of its own: the copy is
   lifted above the scrim, the scrim above the photograph. */
[data-bz-section="post-hero"] [data-bz-node="ph-row"] { position: relative; z-index: 2; }
[data-bz-section="post-hero"] .bz-block { padding-block: 0; }

[data-bz-section="post-hero"] [data-bz-node="ph-crumbs"] .bz-text { max-width: none; }
[data-bz-section="post-hero"] [data-bz-node="ph-crumbs"] p {
  font: 700 var(--text-eyebrow) / 1 var(--font-body);
  letter-spacing: 0.16em; text-transform: uppercase; color: #E2E2E2; margin: 0 0 22px;
}
[data-bz-section="post-hero"] [data-bz-node="ph-crumbs"] a { color: #E2E2E2; text-decoration: none; }
[data-bz-section="post-hero"] [data-bz-node="ph-crumbs"] a:hover { color: #fff; text-decoration: underline; }

[data-bz-section="post-hero"] h1 {
  color: #fff; font-size: 46px; line-height: 1.12; letter-spacing: -0.015em;
  max-width: 820px; margin: 0 0 22px;
}

/* The byline is one line of chips: the topic in the accent, then the date, the
   reading time and the byline itself. A row so each part stays its own block on
   the canvas; flex so the parts sit on one line at their own widths. */
[data-bz-section="post-hero"] [data-bz-node="ph-byline"] {
  display: flex; flex-wrap: wrap; align-items: center; gap: 18px;
}
[data-bz-section="post-hero"] [data-bz-node="ph-byline"] > .bz-col { --bz-span: auto; width: auto; grid-column: auto; }
[data-bz-section="post-hero"] [data-bz-node="ph-topic"] p {
  font: 700 var(--text-eyebrow) / 1 var(--font-body); letter-spacing: 0.14em; text-transform: uppercase;
  background: var(--accent); color: #fff; padding: 7px 11px; margin: 0; display: inline-block;
}
[data-bz-section="post-hero"] [data-bz-node="ph-meta"] p {
  font: 700 var(--text-eyebrow) / 1 var(--font-body); letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--chrome-body); margin: 0;
}
[data-bz-section="post-hero"] [data-bz-node="ph-topic"] .bz-text,
[data-bz-section="post-hero"] [data-bz-node="ph-meta"] .bz-text { max-width: none; }

@media (max-width: 1100px) {
  [data-bz-section="post-hero"] > .bz-section { padding-block: 72px; }
  [data-bz-section="post-hero"] h1 { font-size: 38px; }
}
@media (max-width: 640px) {
  [data-bz-section="post-hero"] > .bz-section { padding-block: 56px; }
  [data-bz-section="post-hero"] h1 { font-size: 28px; }
  [data-bz-section="post-hero"] [data-bz-node="ph-byline"] { gap: 12px; }
}
